sys_script_include.script:
var BNBFixScopeAndMetadata = Class.create();
BNBFixScopeAndMetadata.prototype = {
    BNB_PREFIX: 'banco do nordeste',
    MAX_DETAIL_LINES: 10,

    initialize: function() {
        this._resetStats();
    },

    /*
        Processa todos os certificados agrupados por CN e registra um resumo das ações.
        Retorna { stats, details, summary }.
    */
    main: function() {
        this._resetStats();
        new global.GlideQuery('cmdb_ci_certificate')
            .groupBy('subject_common_name')
            .aggregate('count')
            .select()
            .forEach(function(aggregate) {
                var cn = aggregate.group.subject_common_name;
                if (!cn) {
                    this.stats.skippedEmptyCN++;
                    return;
                }
                this.stats.commonNames++;
                try {
                    this.setActiveCertificateScope(cn);
                } catch (e) {
                    this.stats.errors.push(cn + ': ' + e);
                }
            }.bind(this));

        var summary = this._buildSummary();
        gs.info(summary);
        return {
            stats: this.stats,
            details: this.details,
            summary: summary
        };
    },

    /*
        Seta o escopo do certificado com validade mais recente ou em vigor.
        Para os demais certificados do mesmo domínio, limpa o escopo e remove metadados.
    */
    setActiveCertificateScope: function(commonName) {
        var now = new GlideDateTime();
        var isFirst = true;
        var caScopeDefault = this.getCAScopeFromCN(commonName);
        var updates = {};

        var grCert = new GlideRecord('cmdb_ci_certificate');
        grCert.addQuery('subject_common_name', commonName);
        grCert.orderByDesc('valid_to');
        grCert.query();

        while (grCert.next()) {
            this.stats.certificates++;
            var caScope = this._resolveScope(grCert, caScopeDefault);

            if (isFirst && caScope != 'NULL') {
                this.setMetaData(grCert);
            } else {
                this._deleteMetadata(grCert);
                /* limpa CA Scope para remover entrada do painel se estiver vencido (exceto o primeiro) */
                if (this._isExpired(grCert, now)) {
                    caScope = 'NULL';
                }
            }
            // NOTE: kept original behavior - only the first record (highest valid_to)
            // can receive metadata, even when that first record resolves to NULL.
            isFirst = false;

            this.stats.scope[caScope] = (this.stats.scope[caScope] || 0) + 1;

            var result = this.updateCertificate(grCert, caScope);
            if (result) {
                updates[grCert.getUniqueValue()] = result;
                this.details.push(result);
            }
        }
        return updates;
    },

    _resolveScope: function(grCert, caScopeDefault) {
        var certCN = this._lc(grCert.getValue('subject_common_name'));
        var state = grCert.getValue('state');
        var isCA = this._isTrue(grCert.getValue('is_ca'));

        var issuerCN = '';
        if (!grCert.issuer.nil()) {
            var issuer = grCert.issuer.getRefRecord();
            if (issuer && issuer.isValidRecord()) {
                issuerCN = this._lc(issuer.getValue('subject_common_name'));
            }
        }

        if (!issuerCN || state == 'revoked' || state == 'retired' || isCA || issuerCN == certCN) {
            return 'NULL';
        }

        if (caScopeDefault == 'external') {
            var issuerNameField = this._lc(grCert.getValue('issuer_common_name'));
            var org = this._lc(grCert.getValue('subject_organization'));

            if (this._startsWith(issuerNameField, this.BNB_PREFIX) || this._startsWith(issuerCN, this.BNB_PREFIX)) {
                return 'internal';
            }
            if (!this._startsWith(org, this.BNB_PREFIX)) {
                return 'NULL';
            }
        }
        return caScopeDefault;
    },

    /*
        Atualiza renewal_tracking e u_ca_scope somente se houver mudança.
        Retorna uma descrição da alteração, ou null se nada mudou.
    */
    updateCertificate: function(certificate, caScope) {
        var renewalTracking = 'NULL';
        if (caScope == 'internal') {
            renewalTracking = 'priority3';
        } else if (caScope == 'external') {
            renewalTracking = 'priority1';
        }

        // Empty fields come back as null/'' - normalize to 'NULL' so unchanged records are not rewritten
        var curTracking = certificate.getValue('renewal_tracking') || 'NULL';
        var curScope = certificate.getValue('u_ca_scope') || 'NULL';

        if (curTracking == renewalTracking && curScope == caScope) {
            this.stats.unchanged++;
            return null;
        }

        certificate.renewal_tracking = renewalTracking; // 'NULL' clears the field
        certificate.u_ca_scope = caScope;
        if (!certificate.update()) {
            this.stats.errors.push('Update failed: ' + certificate.getValue('subject_common_name') +
                ' (' + certificate.getUniqueValue() + ')');
            return null;
        }
        this.stats.updated++;

        return certificate.getValue('subject_common_name') +
            ' | valid_to: ' + certificate.valid_to.getDisplayValue() +
            ' | scope: ' + curScope + ' -> ' + caScope +
            ' | tracking: ' + curTracking + ' -> ' + renewalTracking +
            ' | template: ' + certificate.cert_template.getDisplayValue();
    },

    setMetaData: function(cert) {
        var daysBeforeExpiry = parseInt(gs.getProperty(
            'glide.discovery.certs.days_before_expiration_to_create_renewal_task', '60'), 10);
        if (isNaN(daysBeforeExpiry)) {
            daysBeforeExpiry = 60;
        }

        var validTo = cert.getValue('valid_to');
        var grMetadata = new GlideRecord('sn_disco_certmgmt_certificate_metadata');
        var isNew = !grMetadata.get('certificate', cert.getUniqueValue());
        if (isNew) {
            grMetadata.initialize();
            grMetadata.certificate = cert.getUniqueValue();
        }

        grMetadata.auto_renew_days_before_expiry = daysBeforeExpiry;
        grMetadata.auto_renew_enabled = true;
        grMetadata.auto_renewal_state = 'ready'; // NOTE: overwrites any in-progress renewal state

        if (validTo) {
            // FIX: renewal date = expiry MINUS the configured days (was valid_to + 60 hardcoded)
            var renewalDate = new GlideDateTime(validTo);
            renewalDate.addDaysUTC(-daysBeforeExpiry);
            grMetadata.auto_renewal_date = renewalDate;
        }

        if (isNew) {
            grMetadata.insert();
            this.stats.metadataCreated++;
        } else {
            grMetadata.update();
            this.stats.metadataUpdated++;
        }
    },

    _deleteMetadata: function(cert) {
        var grMetadata = new GlideRecord('sn_disco_certmgmt_certificate_metadata');
        grMetadata.addQuery('certificate', cert.getUniqueValue());
        grMetadata.query();
        while (grMetadata.next()) {
            grMetadata.deleteRecord();
            this.stats.metadataDeleted++;
        }
    },

    getCAScopeFromCN: function(commonName) {
        var cn = this._lc(commonName);
        // FIX: internal domains are checked first; before, 'intra.bnb.gov.br' was
        // caught by the 'bnb.gov.br' check and always returned 'external'.
        if (this._matchesDomain(cn, 'intra.bnb.gov.br') ||
            this._matchesDomain(cn, 'intra.bnb') ||
            this._matchesDomain(cn, 'dmz.bnb') ||
            this._matchesDomain(cn, 'dreads.bnb')) {
            return 'internal';
        }
        if (this._matchesDomain(cn, 'bnb.gov.br')) {
            return 'external';
        }
        return 'NULL';
    },

    /* ---------- helpers (ES5-safe) ---------- */

    _isExpired: function(grCert, now) {
        var validTo = grCert.getValue('valid_to');
        if (!validTo) {
            return false;
        }
        return new GlideDateTime(validTo).before(now);
    },

    // Matches the domain itself or any subdomain (anchored on '.')
    _matchesDomain: function(cn, domain) {
        return cn == domain || this._endsWith(cn, '.' + domain);
    },

    _lc: function(value) {
        return value ? String(value).toLowerCase() : '';
    },

    _startsWith: function(str, prefix) {
        return str.indexOf(prefix) === 0;
    },

    _endsWith: function(str, suffix) {
        return str.length >= suffix.length && str.substring(str.length - suffix.length) === suffix;
    },

    _isTrue: function(value) {
        return value === true || value == '1' || value == 'true';
    },

    _resetStats: function() {
        this.details = [];
        this.stats = {
            startedAt: new GlideDateTime().getDisplayValue(),
            commonNames: 0,
            skippedEmptyCN: 0,
            certificates: 0,
            updated: 0,
            unchanged: 0,
            scope: { internal: 0, external: 0, NULL: 0 },
            metadataCreated: 0,
            metadataUpdated: 0,
            metadataDeleted: 0,
            errors: []
        };
    },

    _buildSummary: function() {
        var s = this.stats;
        var lines = [
            '===== BNBFixScopeAndMetadata - Summary =====',
            'Started: ' + s.startedAt + ' | Finished: ' + new GlideDateTime().getDisplayValue(),
            'Common names processed: ' + s.commonNames +
                (s.skippedEmptyCN ? ' (skipped ' + s.skippedEmptyCN + ' empty CN group)' : ''),
            'Certificates evaluated: ' + s.certificates,
            'Certificates updated: ' + s.updated + ' | unchanged: ' + s.unchanged,
            'Resulting scope -> internal: ' + s.scope.internal +
                ' | external: ' + s.scope.external + ' | NULL: ' + s.scope.NULL,
            'Metadata -> created: ' + s.metadataCreated +
                ' | updated: ' + s.metadataUpdated + ' | deleted: ' + s.metadataDeleted,
            'Errors: ' + s.errors.length
        ];

        if (this.details.length) {
            lines.push('--- Changes (showing ' + Math.min(this.details.length, this.MAX_DETAIL_LINES) +
                ' of ' + this.details.length + ') ---');
            lines = lines.concat(this.details.slice(0, this.MAX_DETAIL_LINES));
        }
        if (s.errors.length) {
            lines.push('--- Errors ---');
            lines = lines.concat(s.errors.slice(0, this.MAX_DETAIL_LINES));
        }
        return lines.join('\n');
    },

    type: 'BNBFixScopeAndMetadata'
};
